import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;

class CalculatorTest {
    private Calculator calculator;

    @BeforeEach
    void setUp() {
        calculator = new Calculator();  // fresh instance per test
    }

    @Test
    @DisplayName("Adding two positive numbers returns correct sum")
    void testAdd() {
        // Arrange -- Act -- Assert
        int result = calculator.add(3, 7);
        assertEquals(10, result, "3 + 7 should equal 10");
    }

    @Test
    @DisplayName("Division by zero throws ArithmeticException")
    void testDivideByZero() {
        assertThrows(ArithmeticException.class,
            () -> calculator.divide(10, 0));
    }

    @ParameterizedTest
    @ValueSource(ints = {1, 2, 3, 4, 5})
    @DisplayName("Positive numbers return true from isPositive")
    void testIsPositive(int value) {
        assertTrue(calculator.isPositive(value));
    }

    @AfterEach
    void tearDown() {
        calculator = null;  // cleanup after each test
    }
}

