record ValidationResult(boolean valid, String error) {}
class PasswordValidator {
    ValidationResult validate(String pw) {
        if (pw.length() < 8)
            return new ValidationResult(false, "Password must be at least 8 characters");
        return new ValidationResult(true, null);
    }
}

// 3) REFACTOR — remove the magic number, tests stay green
class PasswordValidator2 {
    private static final int MIN = 8;
    ValidationResult validate(String pw) {
        return pw.length() < MIN
            ? new ValidationResult(false, "Password must be at least " + MIN + " characters")
            : new ValidationResult(true, null);
    }
}
