class PaymentProcessor {
    PaymentResult process(Payment p) {
        if (p.amount() <= 0) return new PaymentResult(false, "Invalid amount");   // branch 1
        if (p.cardNumber().length() != 16) return new PaymentResult(false, "Invalid card"); // branch 2
        return new PaymentResult(true, "Success");                                 // branch 3
    }
}

// Only the happy path: high line coverage, but ~33% BRANCH coverage
@Test void happyPath() {
    var r = processor.process(new Payment(100.0, "1234567812345678"));
    assertThat(r.success()).isTrue(); // branches 1 and 2 never tested
}

// Cover the rejected branches too -> full branch coverage
@Test void rejectsNegativeAmount() {
    assertThat(processor.process(new Payment(-10.0, "1234567812345678")).success()).isFalse();
}
@Test void rejectsBadCardLength() {
    assertThat(processor.process(new Payment(100.0, "123")).success()).isFalse();
}
